def format_session_log(task, rationale, context, session_id):
    """Format a session log entry."""
    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    flags = []
    if context["urgent"]: flags.append("URGENT")
    if context["blockers"]: flags.append("BLOCKER")
    flags_str = " | ".join(flags) if flags else "NORMAL"
    lines = [
        f"--- Session #{session_id} ---",
        f"Time: {ts}",
        f"Priority: {flags_str}",
        f"Task: {task}",
        f"Rationale: {rationale}",
        ""
    ]
    return "\n".join(lines)

