            session_id = len(sessions) + 1
    log_entry = format_session_log(task, rationale, context, session_id)
    with open(memory_file, "a") as f:
        f.write(log_entry)
    print(f"Session #{session_id}: {task}")
    print(f"Rationale: {rationale}")
    print(f"Log appended to: {memory_file}")

if __name__ == "__main__":
